module tb;
  logic clk = 0, rst_n = 0;
  initial forever #5 clk = ~clk;           // 100 MHz, testbench-only

  // Drive on the NEGEDGE (or via a clocking block); sample on posedge.
  // Driving inputs at the same edge the DUT clocks on is a race:
  // the DUT may see the old value or the new one.
  task automatic drive(input logic [7:0] d);
    @(negedge clk);  data <= d;  valid <= 1'b1;
    @(posedge clk);  while (!ready) @(posedge clk);
    @(negedge clk);  valid <= 1'b0;
  endtask

  logic [7:0] data; logic valid, ready;
  initial begin
    repeat (3) @(posedge clk);  rst_n <= 1'b1;
    drive(8'hA5);
    repeat (10) @(posedge clk);
    $display("done"); $finish;
  end
endmodule
// A clocking block does this declaratively, with explicit input skew
// (sample BEFORE the edge) and output skew (drive AFTER it).

