module dut (input logic clk, rst_n, push, pop, output logic [4:0] cnt);
  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) cnt <= '0;
    else begin
      // Immediate assertion: a procedural statement. Evaluates NOW,
      // in the Active region, using CURRENT (pre-NBA) values.
      a_no_ovf: assert (!(push && !pop && cnt == 5'd16))
                else $error("push into full FIFO, cnt=%0d", cnt);
      a_known:  assert (!$isunknown({push, pop}));
      cnt <= cnt + 5'(push) - 5'(pop);
    end
  end
endmodule
// assert  - I claim this. Failure = a bug in the DESIGN.
// assume  - the environment guarantees this. In formal it CONSTRAINS
//           the solver; in simulation it is a check on the TESTBENCH.
// cover   - I want to see this happen. Never reaching it is a
//           verification hole, not a design bug.

