module chk (input logic clk, rst_n, req, gnt, valid, ready,
            input logic [7:0] data);
  // |->  OVERLAPPING implication: consequent checked in the SAME cycle
  //      the antecedent holds.
  a_gnt_excl: assert property (@(posedge clk) disable iff (!rst_n)
                               gnt |-> req);

  // |=>  NON-OVERLAPPING: consequent checked in the NEXT cycle.
  //      Identical to  |-> ##1  consequent.
  a_hold: assert property (@(posedge clk) disable iff (!rst_n)
                           (valid && !ready) |=> $stable(data));

  a_rise: assert property (@(posedge clk) disable iff (!rst_n)
                           $rose(valid) |=> valid || $past($fell(ready)));

  c_bp: cover property (@(posedge clk) valid && !ready);
endmodule
// Sampling is in the PREPONED region - before any RTL runs this
// time step - so an assertion sees the same values the flops do.
// disable iff kills the check during reset instead of failing it.

L0.cloze:
// A concurrent assertion is clocked and samples its expressions in the
