covergroup cg_fifo @(posedge clk);
  cp_occ: coverpoint occupancy {
    bins empty     = {0};
    bins low       = {[1:7]};
    bins high      = {[8:14]};
    bins full      = {15};            // 4 bins
  }
  cp_op: coverpoint op {
    bins wr = {WRITE}; bins rd = {READ}; bins idle = {IDLE};   // 3 bins
  }
  x_stress: cross cp_occ, cp_op {
    illegal_bins never = binsof(cp_occ.full)  && binsof(cp_op.wr);
    illegal_bins none2 = binsof(cp_occ.empty) && binsof(cp_op.rd);
  }                                   // 4*3 = 12, minus 2 = 10 legal
endgroup
