// INFERENCE: describe the behaviour, let the tool pick the primitive.
module inf (input logic clk, input logic [17:0] a, b, output logic [35:0] p);
  always_ff @(posedge clk) p <= a * b;      // -> DSP48, or LUTs, or...
endmodule

