//     .CLK(clk), .A({7'b0, a}), .B(b), .P(p_wide), ... );
//
// Infer by default. Instantiate only when you must:
//   - clock resources: MMCM/PLL, BUFG, IDELAY  (never inferable)
//   - I/O: IOBUF, ISERDES, differential buffers
//   - a primitive feature with no RTL expression (DSP pre-adder,
//     cascade paths, hard block RAM ECC)
//   - when inference measurably failed and you have the report to
//     prove it - not because you assume it will
